shellCommands.command:
cat .gitignore && cat > src/__smoke.test.tsx <<'EOF'
import { test, expect } from 'vitest';
import * as React from 'react';
import { renderToStaticMarkup } from 'react-dom/server';
import { ThemeProvider } from '@gravity-ui/uikit';
import { App } from './App';

test('renders table with 10 rows per page and selection checkboxes', () => {
  const html = renderToStaticMarkup(<ThemeProvider theme="light"><App /></ThemeProvider>);
  const bodyRows = html.split('<tbody').slice(1).join('').split('<tr').length - 1;
  console.log('tbody rows:', bodyRows, 'checkboxes:', (html.match(/type="checkbox"/g) || []).length);
  console.log('selected text:', html.match(/Выбрано строк: \d+/)?.[0]);
  console.log('first id:', html.match(/ORD-\d+/)?.[0]);
  expect(html).toContain('Выбрано строк: 0');
  expect(html).toContain('ORD-1000');
});
EOF
npx vitest run src/__smoke.test.tsx 2>&1 | grep -v "npm warn" | tail -30; rm -f src/__smoke.test.tsx; git status --short

rm -rf dist && cat > vitest.smoke.config.ts <<'EOF'
